import os
import requests

def score_image_safety(payload, config=None):
    config = config or {}
    api_key = os.environ.get('CONTENT_MODERATION_API_KEY')
    endpoint = "https://api.cognitive.microsoft.com/vision/v3.2/analyze"

    headers = {
        "Ocp-Apim-Subscription-Key": api_key,
        "Content-Type": "application/octet-stream"
    }

    params = {
        "visualFeatures": "Adult,ImageType,Face,Color"
    }

    result = requests.post(endpoint, headers=headers, params=params, data=payload)
    return result.json()
